def top_spenders(self, month: str, n: int) -> List[Tuple[str, Decimal]]:
    # Aggregate total cost per user for given month, omit zero cost.
    costs: Dict[str, Decimal] = {}
    for e in self.entries:
        if e.month != month:
            continue
        costs[e.user_id] = costs.get(e.user_id, Decimal("0")) + e.cost
    # Remove zero-cost users
    filtered = [(uid, amt) for uid, amt in costs.items() if amt != Decimal("0")]
    # Sort by cost descending, then user_id ascending
    filtered.sort(key=lambda x: (-x[1], x[0]))
    return filtered[:n]

